    for i in range(n):
        j = 0
        while j < m:
            if grid[i][j] == 'L' and j+1 < m and grid[i][j+1] == 'R':
                tiles.append((i, j, 'H'))
                j += 2
            elif grid[i][j] == 'U' and i+1 < n and grid[i+1][j] == 'D':
                tiles.append((i, j, 'V'))
                j += 1
            else:
