    n = len(grid)
    m = len(grid[0]) if n > 0 else 0
    new_grid = [list(row) for row in grid]
    # Rotate 2x2 block starting at (row-1, col-1)
    r, c = row-1, col-1
    if r+1 >= n or c+1 >= m:
        return grid
    # Save the 2x2 block
    block = [
        [new_grid[r][c], new_grid[r][c+1]],
        [new_grid[r+1][c], new_grid[r+1][c+1]]
    ]
    # Rotate 90 degrees clockwise
    rotated = [
