    new_grid[r][c] = rotated[0][0]
    new_grid[r][c+1] = rotated[0][1]
    new_grid[r+1][c] = rotated[1][0]
    new_grid[r+1][c+1] = rotated[1][1]
    return [''.join(row) for row in new_grid]

