        desired_v = sum(1 for (x, y, typ) in desired_tiles if y == j and typ == 'V')
        if current_v % 2 != desired_v % 2:
            return -1

    # BFS approach to find the solution
    from collections import deque
    visited = set()
    queue = deque()
    initial_state = tuple(tuple(row) for row in current)
    queue.append((initial_state, []))
    visited.add(initial_state)

    while queue:
        state, ops = queue.popleft()
        if state == tuple(tuple(row) for row in desired):
            return ops
        # Generate all possible operations
        for i in range(1, n):
            for j in range(1, m):
                new_state = apply_operation([list(row) for row in state], i, j)
                new_state_tuple = tuple(tuple(row) for row in new_state)
                if new_state_tuple not in visited:
                    visited.add(new_state_tuple)
                    queue.append((new_state_tuple, ops + [(i, j)]))
                    if len(ops) >= 100000:
                        return -1
    return -1

def main():
    n, m, current, desired = read_input()
    solution = find_solution(n, m, current, desired)
    if solution == -1:
        print(-1)
    else:
        print(len(solution))
        for op in solution:
            print(op[0], op[1])

if __name__ == '__main__':
    main()
